// claims 校验：exp / nbf / aud / iss / iat —— 全部用固定时间戳，输出布尔判据
const crypto = require('crypto');
const SECRET = Buffer.from('ch06-claims-demo-secret');
const NOW = 1700000000;   // 固定"当前时间"，避免输出依赖墙钟

function b64urlEncode(input) {
  const buf = Buffer.isBuffer(input) ? input : Buffer.from(String(input), 'utf8');
  return buf.toString('base64').replace(/=+$/g, '').replace(/\+/g, '-').replace(/\//g, '_');
}
function b64urlDecodeToBuffer(s) {
  const pad = s.length % 4 === 0 ? '' : '='.repeat(4 - (s.length % 4));
  return Buffer.from(s.replace(/-/g, '+').replace(/_/g, '/') + pad, 'base64');
}
function sign(payload) {
  const h = b64urlEncode(JSON.stringify({ alg: 'HS256', typ: 'JWT' }));
  const p = b64urlEncode(JSON.stringify(payload));
  const s = b64urlEncode(crypto.createHmac('sha256', SECRET).update(h + '.' + p).digest());
  return h + '.' + p + '.' + s;
}
function validate(token, now, opts) {
  const parts = token.split('.');
  if (parts.length !== 3) return { ok: false, reasons: ['malformed'] };
  const [h, p, sg] = parts;
  const header = JSON.parse(b64urlDecodeToBuffer(h).toString('utf8'));
  if (header.alg !== 'HS256') return { ok: false, reasons: ['alg'] };
  const expected = crypto.createHmac('sha256', SECRET).update(h + '.' + p).digest();
  const got = b64urlDecodeToBuffer(sg);
  if (!(expected.length === got.length && crypto.timingSafeEqual(expected, got))) {
    return { ok: false, reasons: ['signature'] };
  }
  const c = JSON.parse(b64urlDecodeToBuffer(p).toString('utf8'));
  const reasons = [];
  if (typeof c.exp !== 'number') reasons.push('exp-missing');
  else if (now >= c.exp) reasons.push('expired');
  if (typeof c.nbf === 'number' && now < c.nbf) reasons.push('not-yet-valid');
  if (opts.aud !== undefined && c.aud !== opts.aud) reasons.push('aud-mismatch');
  if (opts.iss !== undefined && c.iss !== opts.iss) reasons.push('iss-mismatch');
  return { ok: reasons.length === 0, reasons };
}

const OPTS = { aud: 'api.example.com', iss: 'https://auth.example.com' };
const base = { sub: 'u1', aud: OPTS.aud, iss: OPTS.iss };
const mk = (extra) => Object.assign({}, base, extra || {});   // base 在前，extra 覆盖

function show(name, payload, now) {
  const r = validate(sign(payload), now, OPTS);
  console.log(name + ' ok=' + r.ok + ' reasons=' + JSON.stringify(r.reasons));
}

show('valid', mk({ exp: NOW + 900, nbf: NOW - 60 }), NOW);
show('expired', mk({ exp: NOW - 1 }), NOW);
show('exp_boundary', mk({ exp: NOW }), NOW);          // exp 边界：now>=exp 即过期
show('nbf_future', mk({ exp: NOW + 900, nbf: NOW + 60 }), NOW);
show('aud_wrong', mk({ exp: NOW + 900, aud: 'evil.example.com' }), NOW);
show('iss_wrong', mk({ exp: NOW + 900, iss: 'https://evil.example.com' }), NOW);
show('missing_exp', { sub: 'u1' }, NOW);
console.log('clock_is_fixed=' + (NOW === 1700000000));
